 1	import java.util.ArrayList;
 2	import java.util.List;
 3	import java.util.Objects;
 4	
 5	public final class NaivePatternSearch {
 6	
 7	    private static final String DEFAULT_TEXT = "aabaacaadaabaaba";
 8	    private static final String DEFAULT_PATTERN = "aaba";
 9	
10	    private NaivePatternSearch() {
11	    }
12	
13	    public static List<Integer> search(String pattern, String text) {
14	        Objects.requireNonNull(pattern, "pattern must not be null");
15	        Objects.requireNonNull(text, "text must not be null");
16	
17	        int patternLength = pattern.length();
18	        int textLength = text.length();
19	
20	        if (patternLength > textLength) {
21	            return List.of();
22	        }
23	
24	        List<Integer> matchIndexes = new ArrayList<>();
25	
26	        for (int startIndex = 0; startIndex <= textLength - patternLength; startIndex++) {
27	            if (matchesAt(pattern, text, startIndex, patternLength)) {
28	                matchIndexes.add(startIndex);
29	            }
30	        }
31	
32	        return matchIndexes;
33	    }
34	
35	    public static String formatMatches(List<Integer> matches) {
36	        Objects.requireNonNull(matches, "matches must not be null");
37	
38	        if (matches.isEmpty()) {
39	            return "";
40	        }
41	
42	        StringBuilder formattedMatches = new StringBuilder();
43	        for (int index = 0; index < matches.size(); index++) {
44	            if (index > 0) {
45	                formattedMatches.append(' ');
46	            }
47	            formattedMatches.append(matches.get(index));
48	        }
49	
50	        return formattedMatches.toString();
51	    }
52	
53	    private static boolean matchesAt(
54	            String pattern, String text, int startIndex, int patternLength) {
55	        for (int offset = 0; offset < patternLength; offset++) {
56	            if (text.charAt(startIndex + offset) != pattern.charAt(offset)) {
57	                return false;
58	            }
59	        }
60	
61	        return true;
62	    }
63	
64	    public static void main(String[] args) {
65	        String text = args.length > 0 ? args[0] : DEFAULT_TEXT;
66	        String pattern = args.length > 1 ? args[1] : DEFAULT_PATTERN;
67	
68	        List<Integer> matches = search(pattern, text);
69	        System.out.println(formatMatches(matches));
70	    }
71	}

